// noteBus: the shared NOTE BUS of HM2 (heart of the audio-reactive visuals v2).
//
// Our edge over Tetris Effect: their visuals CHASE the sound through FFT.
// Our music is generated by code, so the engine knows every note BEFORE it
// sounds. Both music engines (music.ts and music-strudel.ts) publish a NoteEvent
// here with a `when` field (ctx time at which the note will sound). The visuals
// subscribe and schedule the animation FOR `when`: they do not catch up with the
// note, they MEET it at the moment it sounds.
//
// Headless check: the console.debug('[hm-notebus]', layer, 'when', ...) logs;
// the first ~64 events are logged, then it goes quiet (so the console is not flooded).

export type NoteLayer = 'pad' | 'bass' | 'arp' | 'spark'

export interface NoteEvent {
  layer: NoteLayer
  midi: number // MIDI note (pitch drives the drop's position/hue)
  when: number // ctx.currentTime at which the note sounds (visuals schedule for it)
  dur: number // duration, seconds
  velocity: number // 0..1 strength
}

type NoteListener = (e: NoteEvent) => void

class NoteBus {
  private listeners = new Set<NoteListener>()
  private logged = 0
  private readonly logCap = 64

  /** visuals subscribe; returns the unsubscribe function */
  on(fn: NoteListener): () => void {
    this.listeners.add(fn)
    return () => { this.listeners.delete(fn) }
  }

  /** the music engine publishes a note (ahead of `when`, before it sounds) */
  emit(e: NoteEvent): void {
    for (const l of this.listeners) l(e)
    if (this.logged < this.logCap) {
      this.logged++
      console.debug('[hm-notebus]', e.layer, 'when', e.when.toFixed(3), 'midi', String(e.midi))
      if (this.logged === this.logCap) console.debug('[hm-notebus]', 'log-cap', 'дальше тихо')
    }
  }
}

/** one bus for the whole app */
export const noteBus = new NoteBus()
